{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C36", "C53", "C57", "C60", "C70", "C75", "C85"],
  "contradictory_card_ids": ["C02", "C04", "C23", "C33", "C50", "C63"],
  "prediction_basis_card_ids": ["C36", "C60", "C70", "C75", "C85"],
  "claims": [
    {
      "claim": "The query is an N-methyl-4,5-epoxymorphinan with 6-keto and 14-hydroxy groups, i.e. the naloxone-like scaffold. C36 reports that naloxegol has better and more reproducible oral bioavailability than naloxone because glucuronidation is a minor clearance route for naloxegol; the query lacks PEGylation and retains the naloxone-like scaffold, supporting a first-pass liability.",
      "card_ids": ["C36", "C53", "C57"]
    },
    {
      "claim": "C60 reports pentazocine F = 0.18 ± 0.05 in healthy controls, an affirmative measured value below the 20% threshold for a high-first-pass opioid. The cirrhosis records (C07, C13) show higher F only because reduced first-pass metabolism, so they do not transfer to the non-cirrhotic query.",
      "card_ids": ["C60", "C07", "C13"]
    },
    {
      "claim": "L3 naltrexone-related records show 6-β-naltrexol Cmax of 20.4 pg/mL fasted and 64.4 pg/mL fed after oral extended-release naltrexone, consistent with extensive first-pass conversion of the 6-keto/14-hydroxy morphinan scaffold.",
      "card_ids": ["C70", "C75", "C85"]
    },
    {
      "claim": "L4 records show related morphinans are well absorbed (codeine Fa >90% and permeability higher than metoprolol; morphine salts 57–64.5 mg/mL; dextromethorphan almost completely absorbed), but these are absorption measures and do not quantify first-pass metabolism of the query.",
      "card_ids": ["C135", "C136", "C145", "C161", "C162", "C166", "C158", "C147"]
    },
    {
      "claim": "Codeine F = 80.5% and relative bioavailability values of 50–55% are less transferable because codeine lacks the 6-keto and 14-hydroxy groups; naloxegol F = 0.90 is not transferable because PEGylation confers its oral bioavailability.",
      "card_ids": ["C04", "C23", "C33", "C50", "C63", "C02"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C135", "C136", "C145", "C161", "C162", "C166", "C158", "C147"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule is provided.",
    "No matched oral-versus-IV exposure comparison for the query is available.",
    "L4 contains no query-specific or oxymorphone-specific permeability/solubility data; only scaffold analogs such as codeine, morphine, and dextromethorphan.",
    "No query-specific first-pass, glucuronidation, or clearance quantification is supplied.",
    "Transfer from pentazocine (benzomorphan) and from naloxone/naltrexone (different N-substituents) to the N-methyl query is indirect."
  ],
  "decision_summary": "L4 intestinal absorption/permeability records show related morphinans are well absorbed, but they do not address the first-pass metabolism that drives the low-F inference for the 6-keto/14-hydroxy morphinan query. The affirmative sub-20% evidence (pentazocine control F = 0.18 and the naloxone-like scaffold's poorer oral bioavailability relative to PEGylated naloxegol, plus naltrexol first-pass records) remains the basis for predicting low. Prediction kept at low with moderate confidence."
}

